Array.prototype.myFlat = function(depth = 1) {
  const result = [];

  function flatten(arr, currentDepth) {
    for (let i = 0; i < arr.length; i++) {
      if (i in arr) {
        const item = arr[i];
        if (Array.isArray(item) && currentDepth < depth) {
          flatten(item, currentDepth + 1);
        } else {
          result.push(item);
        }
      }
    }
  }

  flatten(this, 0);
  return result;
};
